const MOBILE_DAYS=["d9","d10","d11","d12","d13","d14","d15","d16","d17","d18","d19"];
function mobileSwitchDay(dayKey){
  if(!dayConfigs[dayKey] || dayKey===currentDay)return;
  switchDay(dayKey);
}
function mobileShiftDay(delta){
  const i=Math.max(0,MOBILE_DAYS.indexOf(currentDay));
  const next=MOBILE_DAYS[Math.max(0,Math.min(MOBILE_DAYS.length-1,i+delta))];
  mobileSwitchDay(next);
}
el("mobileDaySelect")?.addEventListener("change",e=>mobileSwitchDay(e.target.value));
el("mobileDaySelect")?.addEventListener("input",e=>mobileSwitchDay(e.target.value));
el("mobilePrevDay")?.addEventListener("click",()=>mobileShiftDay(-1));
el("mobileNextDay")?.addEventListener("click",()=>mobileShiftDay(1));

